pub fn next_phase_at_slot<P: Preset>(&self, slot: Slot) -> Option<Phase> {
    self.fork_slots::<P>()
        .find(|(_, fork_slot)| Some(slot) < fork_slot.into_option())
        .map(|(phase, _)| phase)
}

